template<int N> void mm(const float* A, const float* B, float* C) {
    for (int r = 0; r < N; ++r) {
        const float* a_row = A + r * N;
        float* c_row = C + r * N;
        for (int k = 0; k < N; ++k) {
            const float a = a_row[k];
            const float* b_row = B + k * N;
            for (int c = 0; c < N; ++c)
